66	/// Type-rank for a total ordering across JSON value kinds, so comparisons of
67	/// differing types are deterministic instead of collapsing to `Equal`.
68	fn type_rank(v: &Value) -> u8 {
69	    match v {
70	        Value::Null => 0,
71	        Value::Bool(_) => 1,
72	        Value::Number(_) => 2,
73	        Value::String(_) => 3,
