/// `true` when a shared provider declared `status` in its `reauth_statuses`.
fn provider_wants_reauth(&self, status: u16) -> bool {
    self.auth_provider
        .as_ref()
        .is_some_and(|p| p.reauth_statuses().contains(&status))
}

