398	    fn stream_pages_inner(
399	        &self,
400	        context: Option<&HashMap<String, Value>>,
401	    ) -> Pin<Box<dyn Stream<Item = Result<faucet_core::StreamPage, FaucetError>> + Send + '_>> {
402	        // Clone the context into an owned map so it can live inside the
403	        // `async_stream` generator without borrowing from the caller.
404	        let owned_context: Option<HashMap<String, Value>> = context.cloned();
405	
406	        Box::pin(async_stream::try_stream! {
407	            // Async-job lifecycle (#514): submit → poll → fetch replaces the
408	            // normal single-GET + pagination flow and yields one result page.
409	            if self.config.async_job.is_some() {
410	                let records = self.run_async_job().await?;
411	                yield faucet_core::StreamPage { records, bookmark: None };
412	                return;
413	            }
414	
415	            // Resolve the effective start-bookmark once at the top of the stream.
416	            // A runtime override (applied via `Source::apply_start_bookmark` —
417	            // typically by the pipeline reading from a `StateStore`) takes
418	            // precedence over the static config value.
419	            let effective_start: Option<Value> = {
420	                let guard = self.runtime_start.lock().await;
421	                guard
422	                    .clone()
423	                    .or_else(|| self.config.start_replication_value.clone())
424	            };
425	
426	            let mut state = PaginationState::default();
427	            let mut pages_fetched = 0usize;
428	            let mut running_max: Option<Value> = effective_start.clone();
429	            let mut bookmark_emitted = false;
430	
431	            // H13 (audit #146): combining `max_pages` with incremental
432	            // replication only makes safe forward progress when the API returns
433	            // rows ordered ascending by the replication key. On truncation we
434	            // advance the bookmark to the max key seen so far (so the next run
435	            // resumes past it — without this the stream would re-read the same
436	            // first `max_pages` window forever and never progress); but if the
437	            // feed is unordered, unfetched later pages may hold lower keys that
438	            // resuming past `running_max` would then drop. Warn loudly so the
439	            // requirement is explicit rather than a silent data-loss edge.
440	            if self.config.max_pages.is_some()
441	                && self.config.replication_method == ReplicationMethod::Incremental
442	                && self.config.replication_key.is_some()
443	            {
444	                tracing::warn!(
445	                    "max_pages combined with incremental replication assumes the API returns rows \
446	                     ordered ascending by the replication key; an unordered feed can drop unfetched \
447	                     lower-key records on resume. Ensure ordering, or remove max_pages for a full \
448	                     incremental sweep."
449	                );
450	            }
451	
452	            loop {
453	                if let Some(max) = self.config.max_pages
454	                    && pages_fetched >= max
455	                {
456	                    tracing::warn!("max pages ({max}) reached");
457	                    break;
458	                }
459	
460	                let mut params = self.config.query_params.clone();
461	                self.config.pagination.apply_params(&mut params, &state);
462	
463	                let url_override = match &self.config.pagination {
464	                    PaginationStyle::LinkHeader | PaginationStyle::NextLinkInBody { .. } => {
465	                        state.next_link.clone()
466	                    }
467	                    _ => None,
468	                };
469	
470	                // POST-search (CursorInBody): the extracted cursor is injected
471	                // into the request body for every page after the first.
472	                let body_cursor: Option<(String, String)> = self
473	                    .config
474	                    .pagination
475	                    .body_cursor(&state)
476	                    .map(|(f, v)| (f.to_string(), v.to_string()));
477	
478	                let params_clone = params.clone();
479	                let ctx_ref = owned_context.as_ref();
480	                let is_first_page = pages_fetched == 0;
481	                let body_cursor_ref = body_cursor.as_ref().map(|(f, v)| (f.as_str(), v.as_str()));
482	                let (body, resp_headers) = retry::execute_with_retry(
483	                    // The REST runner takes retries-after-first; the policy holds
484	                    // total attempts. Feed both knobs from the resolved policy so
485	                    // an injected `resilience:` policy (when legacy fields are
486	                    // untouched) governs the retry budget + base backoff while the
487	                    // runner keeps its 429 / `Retry-After` handling.
488	                    self.retry_policy.max_attempts.saturating_sub(1),
489	                    self.retry_policy.base,
490	                    || {
491	                        self.execute_request(
492	                            &params_clone,
493	                            url_override.as_deref(),
494	                            ctx_ref,
495	                            is_first_page,
496	                            body_cursor_ref,
497	                        )
498	                    },
499	                )
500	                .await?;
501	
502	                let raw_records =
503	                    extract::extract_records(&body, self.config.records_path.as_deref())?;
504	                let raw_count = raw_records.len();
505	
506	                let records =
507	                    if self.config.replication_method == ReplicationMethod::Incremental {
508	                        if let (Some(key), Some(start)) =
509	                            (&self.config.replication_key, effective_start.as_ref())
510	                        {
511	                            filter_incremental(raw_records, key, start)
512	                        } else {
513	                            raw_records
514	                        }
515	                    } else {
516	                        raw_records
517	                    };
518	
519	                // Track the running max replication value across pages so the
520	                // final page can carry the consolidated bookmark. When the
521	                // replication bind declares `advance_from`, the next bookmark is
522	                // read from that JSONPath in the **response body** (#513);
523	                // otherwise it is `max(record[replication_key])`.
524	                if self.config.replication_method == ReplicationMethod::Incremental {
525	                    let page_max: Option<Value> = match self
526	                        .config
527	                        .replication_bind
528	                        .as_ref()
529	                        .and_then(|b| b.advance_from.as_deref())
530	                    {
531	                        Some(path) => faucet_core::util::extract_records(&body, Some(path))
532	                            .ok()
533	                            .and_then(|vs| vs.into_iter().next()),
534	                        None => self
535	                            .config
536	                            .replication_key
537	                            .as_deref()
538	                            .and_then(|key| max_replication_value(&records, key).cloned()),
539	                    };
540	                    if let Some(page_max) = page_max {
541	                        running_max = Some(match running_max.take() {
542	                            Some(prev) => max_value(prev, page_max),
543	                            None => page_max,
544	                        });
545	                    }
546	                }
547	
548	                // Advance pagination state to learn whether there is a next
549	                // page BEFORE yielding the current one. This way the bookmark
550	                // is only attached to pages where `has_next == false`, and we
551	                // never pre-fetch the next page just to classify the current
552	                // one as "final" (which would prevent early exit in callers
553	                // such as `fetch_partition` with `max_records`).
554	                let has_next = self
555	                    .config
556	                    .pagination
557	                    .advance(&body, &resp_headers, &mut state, raw_count)?;
558	                pages_fetched += 1;
559	
560	                if has_next {
561	                    // Intermediate page — yield without bookmark so the
562	                    // pipeline does not persist a partial checkpoint.
563	                    yield faucet_core::StreamPage { records, bookmark: None };
564	                } else if state.current_page_is_duplicate {
565	                    // The content-stagnation guard flagged this page as a
566	                    // duplicate of the previous one — DROP it (do not emit the
567	                    // repeated records to the sink) and stop. The trailing
568	                    // bookmark checkpoint below still fires (#321 L1).
569	                    break;
570	                } else {
571	                    // Final page — attach the consolidated bookmark.
572	                    bookmark_emitted = running_max.is_some();
573	                    yield faucet_core::StreamPage {
574	                        records,
575	                        bookmark: running_max.clone(),
576	                    };
577	                    break;
578	                }
579	
580	                if let Some(delay) = self.config.request_delay {
581	                    tokio::time::sleep(delay).await;
582	                }
583	            }
584	
585	            // Trailing checkpoint: if the loop exited without carrying the
586	            // bookmark on a real page (e.g. via max_pages truncation, or with
587	            // zero pages fetched and a seeded start bookmark), emit one empty
588	            // page carrying the consolidated bookmark so the pipeline still
589	            // persists incremental progress and the next run resumes from here.
590	            // (Safe forward progress under max_pages assumes ascending order by
591	            // the replication key — see the warning emitted above, audit #146 H13.)
592	            if !bookmark_emitted && running_max.is_some() {
593	                yield faucet_core::StreamPage {
594	                    records: Vec::new(),
595	                    bookmark: running_max,
596	                };
597	            }
598	        })
599	    }
