        loc.scheme,
        &loc.bucket,
        &staged.key,
        staging.region.as_deref(),
        staging.endpoint.as_deref(),
    )?;
    let creds = staging
        .access_key
        .as_deref()
        .zip(staging.secret_key.as_deref());
    let sql = clickhouse_stage_insert_sql(
        &quote_table(&self.config.table),
        loc.scheme,
        &url,
        creds,
