311	
312	    /// Set the per-page record count for
313	    /// [`Source::stream_pages`](faucet_core::Source::stream_pages).
314	    ///
315	    /// Pass `0` to opt out of batching — the entire document is drained and
316	    /// emitted in a single [`StreamPage`](faucet_core::StreamPage).
317	    pub fn with_batch_size(mut self, batch_size: usize) -> Self {
318	        self.batch_size = batch_size;
319	        self
320	    }
321	
322	    /// Validate the configuration, surfacing SOAP-specific conflicts as
323	    /// [`FaucetError::Config`] before any request is made.
324	    ///
325	    /// Rules:
326	    /// - both the top-level [`body`](Self::body) and [`SoapConfig::body_inner`]
327	    ///   set is ambiguous;
328	    /// - a [`soap`](Self::soap) block requires `method: POST` (SOAP is a POST
329	    ///   protocol).
330	    ///
331	    /// A no-op (always `Ok`) when no `soap` block is present, so non-SOAP
332	    /// configs are unaffected.
333	    pub fn validate(&self) -> Result<(), FaucetError> {
334	        if let Some(soap) = &self.soap {
335	            if self.body.is_some() && soap.body_inner.is_some() {
336	                return Err(FaucetError::Config(
337	                    "xml: set either the top-level `body` or `soap.body_inner`, not both \
338	                     (ambiguous request body)"
339	                        .into(),
340	                ));
341	            }
342	            if self.method == reqwest::Method::GET {
343	                return Err(FaucetError::Config(
344	                    "xml: a `soap` block requires `method: POST` — SOAP is a POST protocol".into(),
345	                ));
346	            }
347	        }
348	        if let Some(tls) = &self.tls {
349	            tls.validate()?;
350	        }
351	        Ok(())
352	    }
353	}
