178	/// Minimal glob: `*` matches any run. Supports `*.ext`, `prefix*`, `*mid*`,
179	/// `*a*b*`, and exact names.
180	fn glob_match(pattern: &str, name: &str) -> bool {
181	    if !pattern.contains('*') {
182	        return pattern == name;
183	    }
184	    let parts: Vec<&str> = pattern.split('*').collect();
185	    let mut pos = 0usize;
186	    for (i, part) in parts.iter().enumerate() {
187	        if part.is_empty() {
188	            continue;
189	        }
190	        if i == 0 {
191	            if !name[pos..].starts_with(part) {
192	                return false;
193	            }
194	            pos += part.len();
195	        } else if i == parts.len() - 1 {
196	            return name[pos..].ends_with(part);
197	        } else {
198	            match name[pos..].find(part) {
199	                Some(idx) => pos += idx + part.len(),
200	                None => return false,
201	            }
202	        }
203	    }
204	    true

