310	                    }
311	                    page_number = page_number.map(|p| p + 1);
312	                }
313	                Some(XmlPagination::Offset { limit, .. }) => {
314	                    if record_count < *limit {
315	                        break;
316	                    }
317	                    offset += record_count;
318	                }
319	                None => break,
320	            }
321	        }
322	
323	        tracing::info!(
324	            records = all_records.len(),
325	            pages = pages_fetched,
326	            "XML fetch complete"
